import{_ as t}from"./chunks/login-page.DiTLb9-p.js";import{_ as o,c as r,o as n,ae as s}from"./chunks/framework.CDjunVez.js";const a="/assets/portal_en.BEMm199_.png",i="/assets/desk-en.DcIBQzvc.png",f=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick-start.md","filePath":"en/quick-start.md","lastUpdated":1766459798000}'),l={name:"en/quick-start.md"};function c(u,e,g,d,p,m){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Welcome to the <strong>Owl Eye Alert Platform</strong>! This guide will help you <strong>complete your first login and start using core features within 2 minutes</strong>.</p><h2 id="_1-access-the-system" tabindex="-1">1. Access the System <a class="header-anchor" href="#_1-access-the-system" aria-label="Permalink to &quot;1. Access the System&quot;">​</a></h2><p>From the company intranet, open your browser (Chrome is recommended) and go to:<br><a href="https://owleye.envision-energy.com/#/" target="_blank" rel="noreferrer">https://owleye.envision-energy.com/#/</a></p><blockquote><p>💡 <strong>Tip</strong></p><ul><li>If the page fails to load, please ensure you are connected to the company intranet (or connected via VPN).</li><li>For VPN account requests or client installation, contact the IT Helpdesk via WeCom.</li></ul></blockquote><h2 id="_2-log-in" tabindex="-1">2. Log In <a class="header-anchor" href="#_2-log-in" aria-label="Permalink to &quot;2. Log In&quot;">​</a></h2><ol><li>On the login page, enter your <strong>OA account</strong> (usually your email prefix, e.g., <code>san.zhang</code>) and password.</li><li>Click the <strong>【Log In】</strong> button.</li></ol><p><img src="'+t+'" alt="Login Page"></p><blockquote><p>🔐 <strong>Security Note</strong></p><ul><li>If you forget your password, contact the IT Helpdesk via WeCom for a reset.</li></ul></blockquote><h2 id="_3-select-your-regional-site" tabindex="-1">3. Select Your Regional Site <a class="header-anchor" href="#_3-select-your-regional-site" aria-label="Permalink to &quot;3. Select Your Regional Site&quot;">​</a></h2><p>After successful login, you will be directed to the <strong>Owl Eye Site Selection Portal</strong>. Please select the site that matches your business region:</p><ul><li><strong>Global Site</strong>: For all countries/regions except India</li><li><strong>India Site</strong>: For India operations only</li></ul><p>Click the <strong>【Go】</strong> button to be automatically redirected to your selected site.</p><blockquote><p>🔒 <strong>Data Isolation Notice</strong><br> Per IT information security policy, data between the India Site and Global Site is fully isolated and cannot be accessed across regions.</p></blockquote><p><img src="'+a+'" alt="Site Selection Portal"></p><h2 id="_4-first-time-login-permission-confirmation" tabindex="-1">4. First-Time Login: Permission Confirmation <a class="header-anchor" href="#_4-first-time-login-permission-confirmation" aria-label="Permalink to &quot;4. First-Time Login: Permission Confirmation&quot;">​</a></h2><p>Before your first use, please confirm that system permissions have been granted (one-time setup):</p><ul><li><strong>Alert Recipients / Action Item Assignees</strong>: Permissions are usually auto-provisioned. If you see a “no access” message, please contact your business owner for confirmation.</li><li><strong>Regional Owners / Business Owners / Compliance Committee Members</strong>: Permissions are enabled by default. If personnel changes occur, please contact the product team to update configurations.</li></ul><blockquote><p>✅ Once permissions are confirmed, you will be redirected to the <strong>Workbench Home Page</strong>.</p></blockquote><p><img src="'+i+'" alt="Workbench Home Page"></p><h2 id="_5-start-using-core-features" tabindex="-1">5. Start Using Core Features <a class="header-anchor" href="#_5-start-using-core-features" aria-label="Permalink to &quot;5. Start Using Core Features&quot;">​</a></h2><p>Based on your role, focus on the following modules:</p><table tabindex="0"><thead><tr><th>Role</th><th>Recommended Actions</th></tr></thead><tbody><tr><td><strong>Alert Recipients / Action Item Assignees</strong></td><td>Home → Handle <strong>&quot;Alerts to be confirmed&quot;</strong> or <strong>&quot;Action items&quot;</strong></td></tr><tr><td><strong>Regional Managers</strong></td><td><strong>Alert Application Center</strong> → Select relevant application → Perform alert review and management</td></tr><tr><td><strong>Application Owners</strong></td><td><strong>Alert Application Center</strong> → Select relevant application → Export and analyze alerts</td></tr><tr><td><strong>Model Developers</strong></td><td><strong>Alert Application Center</strong> → Select <strong>&quot;Pilot Run Module&quot;</strong> → Query pilot run results</td></tr></tbody></table><h2 id="_6-get-help" tabindex="-1">6. Get Help <a class="header-anchor" href="#_6-get-help" aria-label="Permalink to &quot;6. Get Help&quot;">​</a></h2><ul><li><strong>FAQ</strong>: See <a href="/faq">FAQ Documentation</a></li><li><strong>Business Support</strong>: Contact your designated business owner</li><li><strong>System Support</strong>: Weilun Ni (<code>weilun.ni1</code>), Yunzhen Fan (<code>yunzhen.fan</code>)</li></ul><blockquote><p>⚠️ <strong>Important Reminder</strong><br> This system handles sensitive business data. Please strictly comply with the company’s <em>Data Security Management Policy</em>.<br><strong>Screenshotting, external sharing, or unauthorized access is strictly prohibited.</strong></p></blockquote>',26)])])}const y=o(l,[["render",c]]);export{f as __pageData,y as default};
